content.text:
{
  "name": "串口文本行读取组件",
  "name_en": "Serial Line Reader",
  "manufacturer": "",
  "description": "非物理软件组件，用于通过串口持续读取按行组织的文本数据并进行缓冲，支持线程模式和非线程模式。适合在实验系统中接收外部串口设备输出的 ASCII 或行式测量数据。",
  "description_en": "A non-physical software component for continuously reading line-based text data from a serial port and buffering it for use in threaded or non-threaded execution. It is suitable for receiving ASCII or other line-oriented measurement data from external serial devices in lab workflows.",
  "actions": [
    {
      "action_name": "auto-clear",
      "description": "清空内部行缓冲区并清除串口输入缓冲区。",
      "description_en": "Clear the internal line buffer and the serial input buffer."
    },
    {
      "action_name": "auto-run",
      "description": "在非线程模式下读取并返回当前批次的行数据。",
      "description_en": "Read and return the current batch of line data in non-threaded mode."
    },
    {
      "action_name": "auto-run_threaded",
      "description": "返回当前已累积的读取结果。",
      "description_en": "Return the currently accumulated readings."
    },
    {
      "action_name": "auto-update",
      "description": "打开串口并在循环中持续读取数据，线程安全地更新已缓冲的行内容。",
      "description_en": "Open the serial port and continuously read data in a loop, updating buffered lines in a thread-safe manner."
    },
    {
      "action_name": "auto-shutdown",
      "description": "停止读取流程并关闭串口相关资源。",
      "description_en": "Stop the reading process and close serial-port-related resources."
    }
  ],
  "tag_hints": [
    "serial communication",
    "line-based data acquisition",
    "ASCII serial data",
    "buffered readings",
    "threaded polling",
    "instrument integration"
  ]
}

